//! The typed API layer (DSN-SDK-001 layer 4, DSN-SDK-012): what code generated by
//! `forge types` (DSN-FRG-102) builds on — [`Typed`] items whose body is a generated
//! struct, generated enums over a class and its subclasses for polymorphic results, and a
//! [`Query`] builder that compiles to DAT-Query (STD-EXPR-010).

use crate::decimal::Decimal;
use crate::error::{Error, Result};
use crate::ops::{Item, Selectors};
use crate::session::Client;
use futures_util::{Stream, StreamExt};
use serde::de::DeserializeOwned;
use serde_json::{Value, json};

/// An item of a known class with its body deserialized into `B`.
#[derive(Debug, Clone)]
pub struct Typed<B> {
    /// The item: identifier, class, version, evidence.
    pub item: Item,
    /// The body.
    pub body: B,
}

impl<B: DeserializeOwned> Typed<B> {
    /// The body of an item as `B` (`MODEL.INVALID_VALUE` when it does not fit).
    pub fn from_item(item: Item) -> Result<Typed<B>> {
        let body = serde_json::from_value(item.body().clone()).map_err(|e| {
            Error::new(
                "MODEL.INVALID_VALUE",
                format!("the body of {} does not fit its type: {e}", item.class()),
                json!({"class": item.class(), "object_id": item.object_id()}),
            )
        })?;
        Ok(Typed { item, body })
    }
}

/// A comparison of the L1 expression language.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cmp {
    /// `==`
    Eq,
    /// `!=`
    Ne,
    /// `<`
    Lt,
    /// `<=`
    Le,
    /// `>`
    Gt,
    /// `>=`
    Ge,
}

impl Cmp {
    fn text(self) -> &'static str {
        match self {
            Cmp::Eq => "==",
            Cmp::Ne => "!=",
            Cmp::Lt => "<",
            Cmp::Le => "<=",
            Cmp::Gt => ">",
            Cmp::Ge => ">=",
        }
    }
}

/// A value a builder compares with.
#[derive(Debug, Clone, PartialEq)]
pub enum Literal {
    /// `null`.
    Null,
    /// A boolean.
    Bool(bool),
    /// An integer.
    Int(i64),
    /// An exact decimal.
    Decimal(Decimal),
    /// A text.
    Text(String),
}

impl From<&str> for Literal {
    fn from(s: &str) -> Literal {
        Literal::Text(s.to_string())
    }
}
impl From<String> for Literal {
    fn from(s: String) -> Literal {
        Literal::Text(s)
    }
}
impl From<i64> for Literal {
    fn from(n: i64) -> Literal {
        Literal::Int(n)
    }
}
impl From<bool> for Literal {
    fn from(b: bool) -> Literal {
        Literal::Bool(b)
    }
}
impl From<Decimal> for Literal {
    fn from(d: Decimal) -> Literal {
        Literal::Decimal(d)
    }
}

/// The L1 literal of a value: strings quoted with the escapes of STD-EXPR-001.
pub fn literal(v: &Literal) -> String {
    match v {
        Literal::Null => "null".into(),
        Literal::Bool(b) => b.to_string(),
        Literal::Int(n) => n.to_string(),
        Literal::Decimal(d) => d.to_string(),
        Literal::Text(s) => {
            let mut out = String::from("\"");
            for ch in s.chars() {
                match ch {
                    '"' | '\\' => {
                        out.push('\\');
                        out.push(ch);
                    }
                    '\n' => out.push_str("\\n"),
                    '\r' => out.push_str("\\r"),
                    '\t' => out.push_str("\\t"),
                    c if (c as u32) < 0x20 || c == '\u{2028}' || c == '\u{2029}' => {
                        out.push_str(&format!("\\u{:04x}", c as u32));
                    }
                    c => out.push(c),
                }
            }
            out.push('"');
            out
        }
    }
}

/// A query of one class (and its subclasses unless [`Query::only`]) that compiles to
/// DAT-Query.
#[derive(Debug, Clone, PartialEq)]
pub struct Query {
    spec: serde_json::Map<String, Value>,
}

impl Query {
    /// A query of a class.
    pub fn new(class: &str) -> Query {
        let mut spec = serde_json::Map::new();
        spec.insert("from".into(), json!(class));
        Query { spec }
    }

    /// Exclude subclasses.
    pub fn only(mut self) -> Query {
        self.spec.insert("only".into(), json!(true));
        self
    }

    /// And an L1 boolean expression over `this`.
    pub fn r#where(mut self, expression: &str) -> Query {
        let w = match self.spec.get("where").and_then(Value::as_str) {
            Some(prev) => format!("({prev}) and ({expression})"),
            None => expression.to_string(),
        };
        self.spec.insert("where".into(), json!(w));
        self
    }

    /// And a comparison of a field with a value (`null` compares with `is null`).
    pub fn filter(self, field: &str, op: Cmp, value: impl Into<Literal>) -> Query {
        let v = value.into();
        match (&v, op) {
            (Literal::Null, Cmp::Eq) => self.r#where(&format!("this.{field} is null")),
            (Literal::Null, Cmp::Ne) => self.r#where(&format!("this.{field} is not null")),
            _ => self.r#where(&format!("this.{field} {} {}", op.text(), literal(&v))),
        }
    }

    /// Lifecycle states.
    pub fn in_states(mut self, states: &[&str]) -> Query {
        self.spec.insert("states".into(), json!(states));
        self
    }

    /// The fields to return.
    pub fn select(mut self, fields: &[&str]) -> Query {
        let paths: Vec<String> = fields.iter().map(|f| format!("this.{f}")).collect();
        self.spec.insert("select".into(), json!(paths));
        self
    }

    /// Then order by a field (`desc` when `descending`).
    pub fn order_by(mut self, field: &str, descending: bool) -> Query {
        let entry = json!({"path": format!("this.{field}"), "dir": if descending { "desc" } else { "asc" }});
        match self.spec.get_mut("order_by").and_then(Value::as_array_mut) {
            Some(list) => list.push(entry),
            None => {
                self.spec.insert("order_by".into(), json!([entry]));
            }
        }
        self
    }

    /// The page size.
    pub fn limit(mut self, n: u32) -> Query {
        self.spec.insert("limit".into(), json!(n));
        self
    }

    /// The DAT-Query object.
    pub fn to_query(&self) -> Value {
        Value::Object(self.spec.clone())
    }

    /// Every result as `T` (a generated struct's [`Typed`] or a generated enum), following
    /// the cursors within one snapshot.
    pub fn run<'a, T: 'a>(
        &self,
        client: &'a Client,
        sel: Selectors,
        convert: fn(Item) -> Result<T>,
    ) -> impl Stream<Item = Result<T>> + 'a {
        let page = self
            .spec
            .get("limit")
            .and_then(Value::as_u64)
            .unwrap_or(100) as u32;
        client
            .query(self.to_query(), sel, page)
            .map(move |r| r.and_then(convert))
    }

    /// Every result in a vector.
    pub async fn all<T>(
        &self,
        client: &Client,
        sel: Selectors,
        convert: fn(Item) -> Result<T>,
    ) -> Result<Vec<T>> {
        let items: Vec<Result<T>> = self.run(client, sel, convert).collect().await;
        items.into_iter().collect()
    }
}

/// Read one object of a class by slug.
pub async fn get(client: &Client, class: &str, slug: &str, sel: &Selectors) -> Result<Item> {
    let vae = client.config().vae.clone();
    client
        .read(&format!("ubos://{vae}/{class}/{slug}"), sel)
        .await
}
